package disaster.rescue; public class RaceConditionDemo {static class Safe{long q=1000; synchronized boolean take(long v){if(q<v)return false;q-=v;return true;}}public static void main(String[]a)throws Exception{Safe s=new Safe();Thread t1=new Thread(()->s.take(700)),t2=new Thread(()->s.take(700));t1.start();t2.start();t1.join();t2.join();System.out.println("Synchronized remaining="+s.q+" L (one request succeeds)");}}
